    if name == "carol":
        return [(d.replace(hour=9), d.replace(hour=12)),
                (d.replace(hour=12, minute=30), d.replace(hour=17))]
    raise ValueError(name)

def extra_blocks(name, day):
    """Buffer rule: Carol needs 15 min after any meeting ending >= 16:45."""
    blocks = []
    if name == "carol":
        for s, e in carol:
            if e.time() >= datetime(2000,1,1,16,45).time():
                blocks.append((e, e + timedelta(minutes=15)))
    return blocks

people = {"alice": alice, "bob": bob, "carol": carol}
DUR = timedelta(hours=1)
valid = []
for offset in range(5):
    day = datetime(2024, 1, 15) + timedelta(days=offset)
    t = day.replace(hour=9, minute=0)
    limit = day.replace(hour=18, minute=0)
    while t + DUR <= limit:
        slot = (t, t + DUR)
        ok = True
        for name, cal in people.items():
            windows = allowed_intervals(name, day)
            if not any(w0 <= slot[0] and slot[1] <= w1 for w0, w1 in windows):
                ok = False; break
            for bs, be in cal + extra_blocks(name, day):
                if slot[0] < be and bs < slot[1]:
                    ok = False; break
            if not ok: break
        if ok:
            valid.append(slot)
        t += timedelta(minutes=1)

print("Total valid 1h slots:", len(valid))
