    print("  ", s, "->", e, "wd=", s.weekday(), "start>=12h:", s.hour >= 12)

# ranking: earliest, then prefer non-Monday, then Alice morning (9-12 start/whole)
def key(slot):
    s, e = slot
    return (s, 1 if s.weekday() == 0 else 0, 0 if e.hour <= 12 else 1)

best = min(valid, key=key)
